    # Move each non-background object as a rigid shape to the right, preserving relative
    # vertical placement, packing the objects in their original top-to-bottom order
    # against the right edge; marker 8 marks the rightmost boundary.
    h, w = len(grid), len(grid[0])
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v not in (0,8): cells[v].append((r,c))
    # Object group by connected components, including same-color cells.
